    const char *getRibbonNameLocalized(const char *englishName, size_t languageIndex)
    {
        if (englishName == nullptr || languageIndex >= LANGUAGE_COUNT)
            return nullptr;
        constexpr size_t count = sizeof(LOCALIZED_RIBBON_NAMES) / sizeof(LOCALIZED_RIBBON_NAMES[0]);
        size_t low = 0, high = count;
        while (low < high)
        {
            const size_t middle = low + (high - low) / 2;
            const int order = std::strcmp(LOCALIZED_RIBBON_NAMES[middle].english, englishName);
            if (order < 0)
                low = middle + 1;
            else if (order == 0)
                return LOCALIZED_RIBBON_NAMES[middle].names[languageIndex];
            else
                high = middle;
        }
        return nullptr;
    }
